def extend(add,CAT):
 id='impl-002_int_pendo__conversion_funnel_analysis'
 events="""SELECT visitor_id,account_id,app_id,CAST(occurred_at AS DATE) event_date,page_id entity_id,num_events,num_minutes,1 typ FROM staging.stg_pendo__event UNION ALL SELECT visitor_id,account_id,app_id,CAST(occurred_at AS DATE),feature_id,num_events,num_minutes,2 FROM staging.stg_pendo__feature_event UNION ALL SELECT visitor_id,account_id,app_id,CAST(occurred_at AS DATE),page_id,count(*),sum(num_minutes),3 FROM staging.stg_pendo__page_event GROUP BY 1,2,3,4,5"""
 visitor=f"""SELECT visitor_id,account_id,app_id,event_date,max(CASE WHEN typ=1 THEN 1 ELSE 0 END) pg,max(CASE WHEN typ=2 THEN 1 ELSE 0 END) ft,max(CASE WHEN typ=3 THEN 1 ELSE 0 END) dp,count(DISTINCT entity_id) FILTER(WHERE typ=1) pages,count(DISTINCT entity_id) FILTER(WHERE typ=2) features,sum(CASE WHEN typ=1 THEN num_events ELSE 0 END)*.1+sum(CASE WHEN typ=2 THEN num_events ELSE 0 END)*.3+sum(CASE WHEN typ=3 THEN num_events ELSE 0 END)*.6+sum(num_minutes)*.05 engagement,sum(num_minutes) all_minutes,sum(CASE WHEN typ=1 THEN num_minutes ELSE 0 END) pgminutes FROM ({events}) GROUP BY 1,2,3,4"""
 old=CAT[id]['sql'].split('WITH daily AS (',1)[1].split('), rates AS',1)[0]
 new=f'SELECT account_id,app_id,event_date,count(DISTINCT visitor_id) total_visitors,count(DISTINCT visitor_id) FILTER(WHERE pg=1) visitors_with_page_views,count(DISTINCT visitor_id) FILTER(WHERE ft=1) visitors_with_feature_use,count(DISTINCT visitor_id) FILTER(WHERE dp=1) visitors_with_deep_engagement FROM ({visitor}) GROUP BY 1,2,3'
 add(id,'daily_event_sources',old,new,'修复同一个daily来源模块：按契约三源UNION ALL与类型存在标志，替代event.num_events/num_minutes代理；不改后续占位或cohort。')
 match='x.account_id IS NOT DISTINCT FROM rates.account_id AND x.app_id IS NOT DISTINCT FROM rates.app_id AND x.event_date IS NOT DISTINCT FROM rates.event_date'
 vals={'avg_engagement_score':('DOUBLE','avg(engagement) FILTER(WHERE pg=1)'), 'avg_pages_per_visitor':('DOUBLE','avg(pages) FILTER(WHERE pg=1)'), 'avg_features_per_user':('DOUBLE','avg(features) FILTER(WHERE ft=1)'), 'high_quality_session_rate':('FLOAT','count(DISTINCT visitor_id) FILTER(WHERE all_minutes>=10 AND pages>=3 AND features>=2)::FLOAT/nullif(count(DISTINCT visitor_id),0)'), 'bounce_rate':('FLOAT','count(DISTINCT visitor_id) FILTER(WHERE NOT (all_minutes>=10 AND pages>=3 AND features>=2) AND NOT (all_minutes>=5 AND pages>=2) AND NOT (pgminutes>=1))::FLOAT/nullif(count(DISTINCT visitor_id),0)')}
 for col,(typ,expr) in vals.items():add(id,col,f'NULL::{typ} {col}',f'(SELECT {expr} FROM ({visitor}) x WHERE {match})::{typ} {col}','仅恢复单个按visitor聚合的指标，daily主行集仍使用原agent来源。')
 for rate,col in [('page_to_feature_conversion_rate','avg_30d_page_to_feature_rate'),('feature_to_deep_conversion_rate','avg_30d_feature_to_deep_rate'),('overall_conversion_rate','avg_30d_overall_conversion_rate')]:
  add(id,col,f'avg({rate}) OVER(PARTITION BY account_id,app_id) {col}',f'(SELECT avg(x.{rate}) FROM rates x WHERE x.account_id=rates.account_id AND x.app_id=rates.app_id AND x.event_date>=current_date-INTERVAL 30 DAY) {col}','按契约日期下界及cohort等值连接恢复一项30日指标。')
 add(id,'funnel_health_rating',"'Poor' funnel_health_rating","CASE WHEN avg_30d_overall_conversion_rate>=.3 THEN 'Excellent' WHEN avg_30d_overall_conversion_rate>=.2 THEN 'Good' WHEN avg_30d_overall_conversion_rate>=.1 THEN 'Fair' ELSE 'Poor' END funnel_health_rating",'恢复固定分类为规定阈值，不改其输入。')
 add(id,'optimization_recommendation',"'Focus on feature discovery and onboarding' optimization_recommendation","CASE WHEN avg_30d_page_to_feature_rate<.2 THEN 'Focus on feature discovery and onboarding' WHEN avg_30d_feature_to_deep_rate<.3 THEN 'Improve feature engagement and user guidance' WHEN NULL::FLOAT>.6 THEN 'Reduce bounce rate through better landing experience' ELSE 'Maintain current optimization efforts' END optimization_recommendation",'恢复建议分支；bounce输入仍保留原NULL占位。')
